(function(){
  'use strict';

  const KEY='fastoolee:pwa:';
  const MANIFEST_URL='https://fastoolee.yaakoubpro.com/manifest.webmanifest';
  const APP_ID='https://fastoolee.yaakoubpro.com/';
  const lang=(document.documentElement.lang||'en').toLowerCase();
  const code=lang.startsWith('ar')?'ar':lang.startsWith('fr')?'fr':lang.startsWith('es')?'es':lang.startsWith('pt')?'pt':'en';
  const copy={
    en:{menu:'Install app',title:'Install Fastoolee in seconds',body:'One tap gives you fast access from your desktop or home screen — free, lightweight and no sign up.',action:'Install now',installing:'Finishing install…',later:'Close',ios:'On iPhone/iPad: tap Share, then “Add to Home Screen”.',fallback:'Use your browser install icon or open the browser menu and choose “Install app” / “Add to Home screen”.',retry:'Installation did not finish. You can try again from the browser install icon or refresh this page.'},
    fr:{menu:'Installer l’app',title:'Installez Fastoolee en quelques secondes',body:'Un seul geste pour accéder plus vite à vos outils depuis le bureau ou l’écran d’accueil — gratuit, léger et sans inscription.',action:'Installer maintenant',installing:'Installation…',later:'Fermer',ios:'Sur iPhone/iPad : touchez Partager puis « Sur l’écran d’accueil ».',fallback:'Utilisez l’icône d’installation du navigateur ou ouvrez son menu puis choisissez « Installer l’application » / « Ajouter à l’écran d’accueil ».',retry:'L’installation ne s’est pas terminée. Réessayez avec l’icône d’installation du navigateur ou actualisez cette page.'},
    es:{menu:'Instalar app',title:'Instala Fastoolee en segundos',body:'Un toque te da acceso rápido desde el escritorio o la pantalla de inicio — gratis, ligero y sin registro.',action:'Instalar ahora',installing:'Terminando…',later:'Cerrar',ios:'En iPhone/iPad: toca Compartir y luego “Añadir a pantalla de inicio”.',fallback:'Usa el icono de instalación del navegador o abre su menú y elige “Instalar aplicación” / “Añadir a pantalla de inicio”.',retry:'La instalación no terminó. Inténtalo de nuevo desde el icono de instalación del navegador o actualiza esta página.'},
    pt:{menu:'Instalar app',title:'Instale o Fastoolee em segundos',body:'Um toque dá acesso rápido pela área de trabalho ou tela inicial — grátis, leve e sem cadastro.',action:'Instalar agora',installing:'Finalizando…',later:'Fechar',ios:'No iPhone/iPad: toque em Compartilhar e depois “Adicionar à Tela de Início”.',fallback:'Use o ícone de instalação do navegador ou abra o menu e escolha “Instalar app” / “Adicionar à tela inicial”.',retry:'A instalação não foi concluída. Tente novamente pelo ícone de instalação do navegador ou atualize esta página.'},
    ar:{menu:'تثبيت التطبيق',title:'ثبّت Fastoolee في ثوانٍ',body:'ضغطة واحدة تمنحك وصولاً أسرع من سطح المكتب أو الشاشة الرئيسية — مجاني، خفيف وبدون تسجيل.',action:'ثبّت الآن',installing:'جاري إكمال التثبيت…',later:'إغلاق',ios:'على iPhone/iPad: اضغط مشاركة ثم «إضافة إلى الشاشة الرئيسية».',fallback:'استخدم أيقونة التثبيت في المتصفح أو افتح قائمته واختر «تثبيت التطبيق» / «إضافة إلى الشاشة الرئيسية».',retry:'لم يكتمل التثبيت. جرّب مجدداً من أيقونة التثبيت في المتصفح أو حدّث الصفحة.'}
  }[code];

  const standalone=()=>window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;
  const safeGet=k=>{try{return localStorage.getItem(KEY+k)}catch{return null}};
  const safeSet=(k,v)=>{try{localStorage.setItem(KEY+k,String(v))}catch{}};
  const safeRemove=k=>{try{localStorage.removeItem(KEY+k)}catch{}};

  let deferredPrompt=null;
  let banner=null;
  let note=null;
  let installButtons=[];
  let installedThisSession=false;
  let installCheckToken=0;

  const visits=(Number(safeGet('visits'))||0)+1;
  safeSet('visits',visits);

  function dismissedAllowed(){
    const d=Number(safeGet('dismissedAt'))||0;
    return !d||visits-d>=2;
  }

  function installIcon(){
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12M7 10l5 5 5-5"/><path d="M5 20h14"/></svg>';
  }

  async function detectInstalled(){
    if(standalone())return true;
    if(typeof navigator.getInstalledRelatedApps==='function'){
      try{
        const apps=await navigator.getInstalledRelatedApps();
        const found=apps.some(app=>{
          if(app.platform!=='webapp')return false;
          const url=String(app.url||'');
          const id=String(app.id||'');
          return !url||url===MANIFEST_URL||url.endsWith('/manifest.webmanifest')||id===APP_ID||id==='/'||id===location.origin+'/';
        });
        if(found)safeSet('installedHint','1');
        else safeRemove('installedHint');
        return found;
      }catch{
        /* Fall through to the hint only on browsers without a usable detector. */
      }
    }
    return installedThisSession||safeGet('installedHint')==='1';
  }

  function setButtonsVisible(visible){
    installButtons.forEach(btn=>{btn.hidden=!visible;btn.disabled=false;btn.removeAttribute('aria-busy');const span=btn.querySelector('span');if(span)span.textContent=copy.menu;});
  }

  function ensureMenuButton(){
    const nav=document.querySelector('[data-nav-links]');
    if(!nav)return;
    let btn=nav.querySelector('[data-install-app]');
    if(!btn){
      btn=document.createElement('button');
      btn.type='button';
      btn.className='nav-install-app';
      btn.dataset.installApp='';
      btn.innerHTML=installIcon()+'<span></span>';
      const langMenu=nav.querySelector('.lang-menu');
      nav.insertBefore(btn,langMenu||null);
    }
    const span=btn.querySelector('span');
    if(span)span.textContent=copy.menu;
    installButtons=[...document.querySelectorAll('[data-install-app]')];
    installButtons.forEach(btn=>{
      if(btn.dataset.installBound==='1')return;
      btn.dataset.installBound='1';
      btn.addEventListener('click',installAction);
    });
  }

  function ensureBanner(){
    if(banner&&banner.isConnected)return banner;
    banner=document.createElement('aside');
    banner.className='pwa-install-banner';
    banner.setAttribute('role','dialog');
    banner.setAttribute('aria-label',copy.title);
    banner.innerHTML=`<span class="pwa-install-icon">${installIcon()}</span><div class="pwa-install-copy"><strong></strong><p></p></div><div class="pwa-install-actions"><button class="pwa-install-action" type="button"></button><button class="pwa-install-close" type="button" aria-label="${copy.later}">×</button></div><div class="pwa-install-note" hidden></div>`;
    banner.querySelector('strong').textContent=copy.title;
    banner.querySelector('.pwa-install-copy p').textContent=copy.body;
    banner.querySelector('.pwa-install-action').textContent=copy.action;
    note=banner.querySelector('.pwa-install-note');
    banner.querySelector('.pwa-install-action').addEventListener('click',installAction);
    banner.querySelector('.pwa-install-close').addEventListener('click',dismiss);
    document.body.appendChild(banner);
    return banner;
  }

  function setActionBusy(busy){
    const action=banner&&banner.querySelector('.pwa-install-action');
    if(action){action.disabled=busy;action.textContent=busy?copy.installing:copy.action;action.setAttribute('aria-busy',String(busy));}
    installButtons.forEach(btn=>{btn.disabled=busy;btn.setAttribute('aria-busy',String(busy));});
  }

  function showNote(message){
    ensureBanner();
    note.textContent=message;
    note.hidden=false;
    banner.classList.add('is-visible');
  }

  function clearNote(){if(note){note.hidden=true;note.textContent='';}}

  function showBanner(force=false){
    if(installedThisSession||standalone())return;
    if(!force&&!dismissedAllowed())return;
    ensureBanner();
    clearNote();
    requestAnimationFrame(()=>banner.classList.add('is-visible'));
  }

  function hideBanner(){if(banner)banner.classList.remove('is-visible');}

  function hideInstallUI(){
    hideBanner();
    setButtonsVisible(false);
  }

  function dismiss(){
    safeSet('dismissedAt',visits);
    hideBanner();
  }

  function markInstalled(){
    installedThisSession=true;
    deferredPrompt=null;
    safeSet('installedHint','1');
    document.documentElement.dataset.pwaInstalled='true';
    hideInstallUI();
  }

  function markInstallable(){
    installedThisSession=false;
    safeRemove('installedHint');
    delete document.documentElement.dataset.pwaInstalled;
    setButtonsVisible(true);
  }

  function helpMessage(){
    return /iphone|ipad|ipod/i.test(navigator.userAgent)?copy.ios:copy.fallback;
  }

  async function refreshInstalledState({allowBanner=false}={}){
    const token=++installCheckToken;
    const yes=await detectInstalled();
    if(token!==installCheckToken)return yes;
    if(yes){markInstalled();return true;}
    markInstallable();
    if(allowBanner)showBanner();
    return false;
  }

  async function installAction(){
    if(standalone()){markInstalled();return;}

    /* Re-check before every click. This clears stale state after an uninstall on supported Chromium. */
    if(await detectInstalled()){
      markInstalled();
      return;
    }
    markInstallable();

    if(!deferredPrompt){
      showNote(helpMessage());
      return;
    }

    const promptEvent=deferredPrompt;
    deferredPrompt=null; // A BeforeInstallPromptEvent can only be used once.
    setActionBusy(true);
    clearNote();

    try{
      let result;
      const returned=promptEvent.prompt();
      if(returned&&typeof returned.then==='function')result=await returned;
      if(!result&&promptEvent.userChoice)result=await promptEvent.userChoice;

      if(result&&result.outcome==='dismissed'){
        setActionBusy(false);
        setButtonsVisible(true);
        showBanner(true);
        return;
      }

      /* Do not hide the CTA just because the browser prompt was accepted.
         appinstalled (or a positive installed-app detection) is the authoritative success signal. */
      await new Promise(resolve=>setTimeout(resolve,900));
      const installed=installedThisSession||await detectInstalled();
      setActionBusy(false);
      if(installed){markInstalled();return;}
      setButtonsVisible(true);
      showNote(copy.retry);
    }catch{
      setActionBusy(false);
      setButtonsVisible(true);
      showNote(helpMessage());
    }
  }

  window.addEventListener('beforeinstallprompt',event=>{
    event.preventDefault();
    deferredPrompt=event;
    markInstallable(); // If this fires, the browser considers the PWA installable and not installed.
    clearNote();
    if(dismissedAllowed())showBanner();
  });

  window.addEventListener('appinstalled',markInstalled);

  /* If the user uninstalls while the browser tab is still around, refresh state when they return. */
  window.addEventListener('pageshow',()=>refreshInstalledState({allowBanner:false}));
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshInstalledState({allowBanner:false});});
  window.matchMedia('(display-mode: standalone)').addEventListener?.('change',()=>refreshInstalledState({allowBanner:false}));

  if('serviceWorker'in navigator){
    window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(()=>{}),{once:true});
  }

  ensureMenuButton();
  setButtonsVisible(true);
  refreshInstalledState({allowBanner:true}).then(installed=>{
    if(!installed&&!banner)setTimeout(()=>showBanner(),450);
  });
})();
